<?php
declare(strict_types=1);
$title = 'ประวัติเงินเดือนของฉัน - ระบบบริหารเงินเดือน';
require_once __DIR__ . '/../lib/db.php';
require_once __DIR__ . '/../lib/attendance.php';
$employeeId = (int) authEmployeeId();
$stmt = mysqli_prepare($connection, "SELECT p.year, LOWER(p.month) AS month, p.pay_no,
                                            COALESCE(s.base_salary,p.total_pay) AS base_salary,
                                            COALESCE(s.total_additions,0) AS total_additions,
                                            COALESCE(s.total_deductions,0) AS total_deductions,
                                            COALESCE(s.net_salary,p.total_pay) AS net_salary,
                                            s.payment_note, s.created_at AS paid_at
                                     FROM payment p LEFT JOIN payment_snapshots s ON s.pay_no=p.pay_no
                                     WHERE p.emp_id=? ORDER BY p.year DESC,
                                     FIELD(LOWER(p.month),'december','november','october','september','august','july','june','may','april','march','february','january') ASC,
                                     p.pay_no DESC");
mysqli_stmt_bind_param($stmt, 'i', $employeeId); mysqli_stmt_execute($stmt);
$payments = mysqli_fetch_all(mysqli_stmt_get_result($stmt), MYSQLI_ASSOC);
$total = array_sum(array_map(static fn(array $p): float => (float)$p['net_salary'], $payments));
$thaiMonths = attendanceMonthNames();
$escape = static fn($value): string => htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
?>
<div class="w-full space-y-4"><header class="border-b border-[#dedede] pb-3"><h1 class="text-xl font-semibold text-[#202223]">ประวัติเงินเดือนของฉัน</h1><p class="mt-0.5 text-sm text-[#6d7175]">ดูยอดเงินเดือนที่จ่ายแล้วของบัญชีคุณเท่านั้น</p></header><section class="grid grid-cols-2 overflow-hidden rounded-lg border border-[#dedede] bg-white"><div class="p-4"><p class="text-[12px] text-[#615d59]">จำนวนรายการ</p><p class="mt-1 text-[22px] font-bold"><?= count($payments) ?> <span class="text-[13px] font-normal">รายการ</span></p></div><div class="border-l border-[#e6e6e6] p-4"><p class="text-[12px] text-[#615d59]">ยอดสุทธิรวม</p><p class="mt-1 text-[22px] font-bold">฿<?= number_format($total,2) ?></p></div></section><section class="overflow-hidden rounded-lg border border-[#dedede] bg-white"><?php if ($payments): ?><div class="divide-y divide-[#e6e6e6] md:hidden"><?php foreach($payments as $row): ?><article class="p-4"><div class="flex justify-between gap-3"><div><p class="font-bold"><?= $escape($thaiMonths[$row['month']] ?? $row['month']) ?> <?= $escape($row['year']) ?></p><p class="text-[12px] text-[#615d59]">รายการ #<?= $escape($row['pay_no']) ?></p></div><div class="text-right"><p class="text-[17px] font-bold">฿<?= number_format((float)$row['net_salary'],2) ?></p><span class="text-[12px] text-emerald-700">จ่ายแล้ว</span></div></div><dl class="mt-3 grid grid-cols-2 gap-1 text-[13px]"><dt class="text-[#615d59]">ฐานเงินเดือน</dt><dd class="text-right">฿<?= number_format((float)$row['base_salary'],2) ?></dd><dt class="text-emerald-700">รายรับเพิ่ม</dt><dd class="text-right text-emerald-700">+฿<?= number_format((float)$row['total_additions'],2) ?></dd><dt class="text-red-700">รายการหัก</dt><dd class="text-right text-red-700">-฿<?= number_format((float)$row['total_deductions'],2) ?></dd></dl><?php if($row['payment_note']): ?><p class="mt-3 border-t border-[#e6e6e6] pt-3 text-[12px] text-[#615d59]">หมายเหตุ: <?= $escape($row['payment_note']) ?></p><?php endif; ?></article><?php endforeach; ?></div><div class="hidden md:block"><table class="js-data-table w-full text-left text-[14px]" data-export-name="ประวัติเงินเดือนของฉัน"><thead><tr><th>งวด</th><th>เลขที่รายการ</th><th>ฐานเงินเดือน</th><th>รายรับเพิ่ม</th><th>รายการหัก</th><th>ยอดสุทธิ</th><th>สถานะ</th></tr></thead><tbody><?php foreach($payments as $row): ?><tr><td class="font-bold"><?= $escape($thaiMonths[$row['month']] ?? $row['month']) ?> <?= $escape($row['year']) ?></td><td>#<?= $escape($row['pay_no']) ?></td><td>฿<?= number_format((float)$row['base_salary'],2) ?></td><td class="text-emerald-700">+฿<?= number_format((float)$row['total_additions'],2) ?></td><td class="text-red-700">-฿<?= number_format((float)$row['total_deductions'],2) ?></td><td class="font-bold">฿<?= number_format((float)$row['net_salary'],2) ?></td><td><span class="rounded-full bg-emerald-50 px-2.5 py-1 text-[12px] text-emerald-700">จ่ายแล้ว</span></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="flex min-h-[260px] flex-col items-center justify-center p-8 text-center"><span class="flex h-12 w-12 items-center justify-center rounded-full bg-[#f6f5f4] text-[#8a8580]"><i class="fa-solid fa-receipt"></i></span><h2 class="mt-4 font-bold">ยังไม่มีประวัติเงินเดือน</h2><p class="mt-1 text-[13px] text-[#615d59]">รายการจะแสดงหลังผู้ดูแลบันทึกการจ่ายเงินแล้ว</p></div><?php endif; ?></section></div>
